import csv
import os

class ShoppingCart:
    def __init__(self):
        self.cart_file = "shopping_cart.csv"
        self.products_file = "products.csv"
        # Create cart file with headers if it doesn't exist
        if not os.path.exists(self.cart_file):
            with open(self.cart_file, 'w', newline='') as file:
                writer = csv.writer(file)
                writer.writerow(['product_id', 'product_name', 'quantity', 'price'])

    def get_product_by_id(self, product_id):
        """Retrieve product information by ID from products.csv"""
        if not os.path.exists(self.products_file):
            return None

        with open(self.products_file, 'r') as file:
            reader = csv.DictReader(file)
            for row in reader:
                if int(row['id']) == product_id:
                    return {
                        'id': int(row['id']),
                        'name': row['name'],
                        'price': float(row['price']),
                        'status': row['status']
                    }
        return None

    def add_to_cart(self, product_id, quantity=1):
        """Add a product to the shopping cart"""
        # Check if product exists
        product = self.get_product_by_id(product_id)
        if not product:
            return False, f"Product with ID {product_id} not found"

        if product['status'] != 'in stock':
            return False, f"Product {product['name']} is not in stock"

        # Check if product is already in cart
        cart_items = []
        product_in_cart = False

        if os.path.exists(self.cart_file):
            with open(self.cart_file, 'r') as file:
                reader = csv.DictReader(file)
                for row in reader:
                    if int(row['product_id']) == product_id:
                        # Update quantity
                        new_quantity = int(row['quantity']) + quantity
                        row['quantity'] = str(new_quantity)
                        product_in_cart = True
                    cart_items.append(row)

        if not product_in_cart:
            # Add new product to cart
            cart_items.append({
                'product_id': str(product_id),
                'product_name': product['name'],
                'quantity': str(quantity),
                'price': str(product['price'])
            })

        # Write updated cart back to file
        with open(self.cart_file, 'w', newline='') as file:
            writer = csv.writer(file)
            writer.writerow(['product_id', 'product_name', 'quantity', 'price'])
            for item in cart_items:
                writer.writerow([item['product_id'], item['product_name'], item['quantity'], item['price']])

        return True, f"Added {quantity} of {product['name']} to cart"

    def view_cart(self):
        """Display the contents of the shopping cart"""
        if not os.path.exists(self.cart_file):
            return []

        cart_items = []
        with open(self.cart_file, 'r') as file:
            reader = csv.DictReader(file)
            for row in reader:
                cart_items.append({
                    'product_id': int(row['product_id']),
                    'product_name': row['product_name'],
                    'quantity': int(row['quantity']),
                    'price': float(row['price']),
                    'total': float(row['price']) * int(row['quantity'])
                })
        return cart_items

    def verify_item_in_cart(self, product_id):
        """Verify if a specific product is in the cart"""
        cart_items = self.view_cart()
        for item in cart_items:
            if item['product_id'] == product_id:
                return True, item
        return False, None

def main():
    # Create shopping cart instance
    cart = ShoppingCart()

    # Product ID for V8 Energy Drink
    v8_product_id = 2

    # Add V8 Energy Drink to cart
    success, message = cart.add_to_cart(v8_product_id, 1)
    print(message)

    if success:
        # Verify the item is in the cart
        in_cart, item = cart.verify_item_in_cart(v8_product_id)
        if in_cart:
            print(f"Verification successful: {item['product_name']} is in the cart")
            print(f"Quantity: {item['quantity']}, Price: ${item['price']}, Total: ${item['total']}")
        else:
            print("Verification failed: Item not found in cart")

    # Display full cart contents
    print("\n--- Shopping Cart Contents ---")
    cart_items = cart.view_cart()
    if cart_items:
        total_amount = 0
        for item in cart_items:
            print(f"{item['product_name']} - Quantity: {item['quantity']}, Price: ${item['price']}, Total: ${item['total']}")
            total_amount += item['total']
        print(f"Total Amount: ${total_amount:.2f}")
    else:
        print("Cart is empty")

if __name__ == "__main__":
    main()

